public class Program
{
    public static void main(String[] args) {
        String name = "Toyota";
        double engine = 4.7;
        int year = 2019;
        System.out.println("Name:" + " " + name);
        System.out.println("Engine:" + " " + engine);
        System.out.println("Year:" + " " + year);
	}
}
